function compass(x,y,r){
  return `<g transform="translate(${x} ${y})" opacity=".85"><circle r="${r}" fill="none" stroke="var(--ink-3)" stroke-width=".6"/><circle r="${r*.72}" fill="none" stroke="var(--ink-3)" stroke-width=".4" stroke-dasharray="1 1.5"/>
  <path d="M0 ${-r*1.15} L${r*.18} 0 L0 ${r*1.15} L${-r*.18} 0Z" fill="var(--ink-3)"/><path d="M${-r*1.15} 0 L0 ${r*.18} L${r*1.15} 0 L0 ${-r*.18}Z" fill="var(--ink-3)" opacity=".6"/>
  <path d="M0 ${-r*1.15} L${r*.18} 0 L0 0Z" fill="var(--rojo)"/><text y="${-r*1.3}" text-anchor="middle" class="nlab" style="font-size:7px">N</text></g>`;
}
function baseMap(full){
  let s=full?`<rect class="sea" x="-200" y="-200" width="700" height="760"/>`:"";
  if(!full) for(let lon=-78;lon<=-68;lon+=2){const x=f1(PX(lon)); s+=`<line class="grat" x1="${x}" x2="${x}" y1="-50" y2="420"/><text class="glab" x="${+x+1.5}" y="356">${-lon}° O</text>`;}
  if(!full) for(let lat=-4;lat<=12;lat+=2){const y=f1(PY(lat)); s+=`<line class="grat" x1="-50" x2="350" y1="${y}" y2="${y}"/><text class="glab" x="2" y="${+y-1.5}">${Math.abs(lat)}° ${lat<0?"S":"N"}</text>`;}
  if(full){ s+=REGS.map(r=>`<path class="reg" d="${r.d}" fill="var(${RC[r.n]})"/>`).join("") + DEPS.map(d=>`<path class="dep" d="${d.d}"/>`).join("") + `<path class="outline" d="${OUTLINE}"/>`;
    s+=RLAB.map(r=>`<text class="rlab" x="${f1(PX(r[1]))}" y="${f1(PY(r[2]))}">${r[0]}</text>`).join("");
    s+=`<g><rect x="${f1(PX(-79.95))}" y="${f1(PY(12.75))}" width="34" height="13" fill="none" stroke="var(--ink-3)" stroke-width=".4" stroke-dasharray="1.5 1"/><path d="M${f1(PX(-79.95)+6)} ${f1(PY(12.75)+4)} l1.2 2 -.6 2.2 -1 .4z M${f1(PX(-79.95)+9)} ${f1(PY(12.75)+3)} l.8 1 -.5 .9z" fill="var(--r-caribe)" stroke="var(--land-stroke)" stroke-width=".3"/><text class="dlab" x="${f1(PX(-79.95)+21)}" y="${f1(PY(12.75)+6)}">San Andrés y</text><text class="dlab" x="${f1(PX(-79.95)+21)}" y="${f1(PY(12.75)+10)}">Providencia</text></g>`;
  } else s+=`<path class="land" d="${OUTLINE}"/>`;
  [["Panamá",-79.3,8.4],["Venezuela",-69.6,8.9],["Ecuador",-78.6,-0.8],["Perú",-74.6,-3.2],["Brasil",-67.9,-1.6]].forEach(n=>s+=`<text class="nlab" x="${f1(PX(n[1]))}" y="${f1(PY(n[2]))}" text-anchor="middle">${n[0]}</text>`);
  s+=`<text class="slab" x="${f1(PX(-76.6))}" y="${f1(PY(11.9))}" text-anchor="middle">Mar Caribe</text>`;
  s+=`<text class="slab" transform="translate(${f1(PX(-79.4))} ${f1(PY(4.6))}) rotate(-90)" text-anchor="middle">Océano Pacífico</text>`;
  s+=compass(f1(PX(-79.2)),f1(PY(11.3)),13);
  const sx=PX(-71.2), sy=PY(-3.4), u=19.5/111*200; // 200 km
  s+=`<g><rect x="${f1(sx)}" y="${f1(sy)}" width="${f1(u/2)}" height="2.4" fill="var(--ink-3)"/><rect x="${f1(sx+u/2)}" y="${f1(sy)}" width="${f1(u/2)}" height="2.4" fill="none" stroke="var(--ink-3)" stroke-width=".5"/><text class="glab" x="${f1(sx)}" y="${f1(sy-2)}">0</text><text class="glab" x="${f1(sx+u)}" y="${f1(sy-2)}" text-anchor="middle">200 km</text></g>`;
  if(full==='cities') s+=CITIES.map(c=>`<g class="city ${c[4]||""}"><circle cx="${f1(PX(c[2]))}" cy="${f1(PY(c[1]))}" r="1.3"/><text x="${f1(PX(c[2])+(c[3]>0?2.6:c[3]<0?-2.6:0))}" y="${f1(PY(c[1])+(c[3]===0?7:1.9))}" text-anchor="${c[3]>0?"start":c[3]<0?"end":"middle"}">${c[0]}</text></g>`).join("");
  return s;
}
$("#ghost").innerHTML=baseMap(false)+`<path class="route-done" d="${routeD(10)}" style="opacity:.7"/>`+Q.map(q=>`<circle cx="${f1(PX(q.lon))}" cy="${f1(PY(q.lat))}" r="${f1(R(q.mag))}" fill="var(--rojo)" opacity=".8"/>`).join("");

const BASE=baseMap(true), CITYL=baseMap('cities').split('<path class="outline"')[0]?CITIES.map(c=>`<g class="city ${c[4]||""}"><circle cx="${f1(PX(c[2]))}" cy="${f1(PY(c[1]))}" r="1.3"/><text x="${f1(PX(c[2])+(c[3]>0?2.6:c[3]<0?-2.6:0))}" y="${f1(PY(c[1])+(c[3]===0?7:1.9))}" text-anchor="${c[3]>0?"start":c[3]<0?"end":"middle"}">${c[0]}</text></g>`).join(""):"";
$("#leg-regs").innerHTML=Object.entries(RC).map(([n,c])=>`<span style="margin-right:8px"><span class="sw2" style="background:var(${c})"></span>${n}</span>`).join("");
function renderMap(){
  const q=Q[cur];
  const on=new Set(q.deptos);
  const hl=DEPS.filter(d=>on.has(d.n)).map(d=>d.d).join("");
  let s=BASE+`<mask id="mk" maskUnits="userSpaceOnUse" x="-200" y="-200" width="700" height="760"><rect x="-200" y="-200" width="700" height="760" fill="#fff"/><path d="${hl}" fill="#000"/></mask><rect class="veil" x="-200" y="-200" width="700" height="760" mask="url(#mk)"/>`;
  s+=`<path class="hl" d="${hl}"/>`+DEPS.filter(d=>on.has(d.n)).map(d=>`<text class="dlab on" x="${d.x}" y="${d.y}">${d.n}</text>`).join("")+CITYL;
  Q.forEach((o,i)=>{const x=f1(PX(o.lon)),y=f1(PY(o.lat)),r=R(o.mag);
    s+=`<g class="stop ${i===cur?"cur":seen.has(i)?"seen":""}" data-i="${i}" role="button" tabindex="-1" aria-label="${o.anio} ${esc(o.lugar)}"><circle cx="${x}" cy="${y}" r="${Math.max(r,4.4)+3}" fill="transparent"/><circle class="dot" cx="${x}" cy="${y}" r="${f1(i===cur?Math.max(r,4.6):3.6)}"/><text x="${x}" y="${f1(+y+1.9)}" style="font-size:${i===cur?5.4:4.4}px">${i+1}</text></g>`;});
  const x=f1(PX(q.lon)),y=f1(PY(q.lat));
  s+=`<circle class="ring" cx="${x}" cy="${y}" r="5"/><circle class="ring r2" cx="${x}" cy="${y}" r="5"/><circle class="ring r3" cx="${x}" cy="${y}" r="5"/>`;
  if(cmpWith!==null){const b=Q[cmpWith]; s+=`<circle class="ring b" cx="${f1(PX(b.lon))}" cy="${f1(PY(b.lat))}" r="5"/><circle class="ring b r2" cx="${f1(PX(b.lon))}" cy="${f1(PY(b.lat))}" r="5"/>`;}
  $("#map").innerHTML=s;
  $("#map").setAttribute("aria-label",`Mapa de Colombia. Epicentro ${cur+1} de 10: ${q.lugar}, ${q.anio}.`);
  $("#map").querySelectorAll(".stop").forEach(g=>g.addEventListener("click",e=>{e.stopPropagation(); if(dragMoved){dragMoved=false;return;} stopPlay();go(+g.dataset.i);}));
  zoomTo(q,true);
}
let vb=[0,0,300,360], anim=null;
function zoomTo(q,arrive){
  const z=innerWidth<860?1.5:1.55, w=300/z, h=360/z;
  let cx=PX(q.lon), cy=PY(q.lat);
  const t=[Math.max(-30,Math.min(330-w,cx-w/2)), Math.max(-10,Math.min(370-h,cy-h/2)), w, h];
  if(reduced){vb=t;$("#map").setAttribute("viewBox",vb.map(f1).join(" ")); $("#map").style.setProperty("--zs",Math.min(1.6,Math.max(.35,vb[2]/193.5)).toFixed(3));return;}
  const from=arrive?[t[0]-t[2]*.06,t[1]-t[3]*.06,t[2]*1.12,t[3]*1.12]:vb.slice(), t0=performance.now(), dur=arrive?450:750; cancelAnimationFrame(anim);
  const step=now=>{const k=Math.min(1,(now-t0)/dur), e=1-Math.pow(1-k,3); vb=from.map((v,i)=>v+(t[i]-v)*e); $("#map").setAttribute("viewBox",vb.map(f1).join(" ")); $("#map").style.setProperty("--zs",Math.min(1.6,Math.max(.35,vb[2]/193.5)).toFixed(3)); if(k<1) anim=requestAnimationFrame(step);};
  anim=requestAnimationFrame(step);
}

/* ---------- Nota de campo ---------- */
const PIN=`<svg class="pin" viewBox="0 0 30 34" aria-hidden="true"><line x1="15" y1="16" x2="17" y2="33" stroke="var(--ink-3)" stroke-width="2"/><circle cx="15" cy="12" r="10" fill="var(--pin)"/><circle cx="11.5" cy="8.5" r="3" fill="#fff" opacity=".45"/></svg>`;
const PC='<span class="pc">por confirmar</span>';
function sonda(d){const k=Math.min(d,180)/180*36+2;return `<svg viewBox="0 0 16 40" aria-hidden="true"><rect x="3" y="0" width="10" height="6" fill="var(--strata-1)"/><rect x="3" y="6" width="10" height="8" fill="var(--strata-2)"/><rect x="3" y="14" width="10" height="26" fill="var(--mantle)"/><circle cx="8" cy="${f1(k)}" r="3.2" fill="var(--rojo)"/></svg>`;}
const coord=q=>`${Math.abs(q.lat).toFixed(2).replace(".",",")}° ${q.lat<0?"S":"N"}, ${Math.abs(q.lon).toFixed(2).replace(".",",")}° O`;
function renderNote(){
  const q=Q[cur];
  const muertos=q.sinMuertos?"0":(q.muertosAprox?"≈":"")+fmt(q.muertos);
  const opts=Q.map((o,i)=>i===cur?"":`<option value="${i}" ${i===cmpWith?"selected":""}>${o.anio} · ${esc(o.lugar)}</option>`).join("");
  const n=$("#note");
  n.innerHTML=`${PIN}
    <div class="n-head"><span class="num">Sismo ${cur+1} de 10</span><span class="num">${coord(q)}</span></div>
    <h2><span class="yr num">${q.anio}</span>${esc(q.titulo)}</h2>
    <p class="when">${esc(q.fecha)}, ${esc(q.hora.charAt(0).toLowerCase()+q.hora.slice(1))}</p>
    <div class="stats">
      <div class="stat m"><b class="num">${esc(q.magTxt.replace(" Mw",""))}</b><small>magnitud${q.magPC?" "+PC:""}</small></div>
      <div class="stat"><div class="sonda">${sonda(q.prof)}<b class="num">${esc(q.profTxt.replace("Unos ","≈").replace(" km",""))}<small style="font-size:.5em"> km</small></b></div><small>profundidad del foco</small></div>
      <div class="stat"><b class="num">${muertos}</b><small>${q.sinMuertos?"muertos reportados":"muertos"}${q.victPC?" "+PC:""}</small></div>
    </div>
    <span class="regchip">${REGTXT[q.id][1].map(r=>`<i style="background:var(${RC[r]})"></i>`).join("")}${esc(REGTXT[q.id][0])}</span>
    <p class="where"><b>${esc(q.epicentro)}.</b> Afectó sobre todo: ${esc(q.deptos.join(", "))}.</p>
    <p class="why">${esc(BREVE[q.id])}</p>
    ${ROLD[q.id]?`<p class="rold">${esc(ROLD[q.id])}</p>`:""}
    <div class="acts"><label for="cmp-sel">Comparar con <select id="cmp-sel"><option value="">elige un sismo</option>${opts}</select></label></div>
    <details class="more"><summary>Más datos y fuentes</summary>
      <dl>
        <dt>Hora</dt><dd>${esc(q.hora)}${q.horaNota?". "+esc(q.horaNota):""}</dd>
        <dt>Magnitud</dt><dd>${esc(q.magNota)}</dd>
        <dt>Profundidad</dt><dd>${esc(q.profTxt)}. ${esc(q.profNota)}</dd>
        <dt>Víctimas</dt><dd>${esc(q.victimas)} (${esc(q.victFuente)})</dd>
        <dt>Tectónica</dt><dd>${q.tecto?esc(q.tecto)+" ("+esc(q.tectoFuente)+")":"Por confirmar. "+esc(q.tectoNota)}</dd>
        <dt>Ubicación</dt><dd>${esc(q.ubicNota)}</dd>
      </dl>
      <ul>${q.fuentes.map(k=>`<li><a href="${S[k].u}" target="_blank" rel="noopener">${esc(S[k].t)}</a></li>`).join("")}</ul>
    </details>`;
  n.classList.remove("enter"); void n.offsetWidth; if(!reduced) n.classList.add("enter");
  n.scrollTop=0;
  $("#cmp-sel").addEventListener("change",e=>{ if(e.target.value==="") return; cmpWith=+e.target.value; openCmp(); renderMap(); });
}

/* ---------- Línea de tiempo ---------- */
$("#years").innerHTML=Q.map((q,i)=>{const r=Math.round(5+(q.mag-5.5)*6);return `<button class="yb" type="button" data-i="${i}" aria-label="${q.anio}, ${esc(q.lugar)}, magnitud ${q.magTxt}"><span class="d"><span style="width:${r*2}px;height:${r*2}px"></span></span><span class="y num">${q.anio}</span><span class="l">${esc(q.lugar)}</span></button>`;}).join("");
document.querySelectorAll(".yb").forEach(b=>b.addEventListener("click",()=>{stopPlay();go(+b.dataset.i);}));
function renderStrip(){
  document.querySelectorAll(".yb").forEach(b=>{const i=+b.dataset.i; b.classList.toggle("seen",seen.has(i)); if(i===cur) b.setAttribute("aria-current","true"); else b.removeAttribute("aria-current");});
  const cb=document.querySelector('.yb[aria-current="true"]'); if(cb){const y=$("#years"); y.scrollTo({left:cb.offsetLeft-y.clientWidth/2+cb.offsetWidth/2,behavior:reduced?'auto':'smooth'});}
  $("#prev").disabled=cur<=0; $("#next").disabled=cur===9;
  $("#count").textContent=`${seen.size} de 10 recorridos`;
}

/* ---------- Línea principal ---------- */
const Y0=1976, Y1=2027;
let BX=[], markX=null, mAnim=null;
function layoutBig(){
  const inner=$("#bl-inner"), W=inner.clientWidth, pad=70;
  BX=Q.map(q=>pad+(TT[q.id]-Y0)/(Y1-Y0)*(W-pad*2));
  for(let k=1;k<BX.length;k++) if(BX[k]-BX[k-1]<54) BX[k]=BX[k-1]+54;
  const over=BX[BX.length-1]-(W-pad); if(over>0) BX=BX.map((x,k)=>x-over*(k/(BX.length-1)));
  return {W,pad};
}
const AY=125;
function renderBig(){
  const {W,pad}=layoutBig(), X=yr=>pad+(yr-Y0)/(Y1-Y0)*(W-pad*2);
  let s=`<line class="bl-axis" x1="${pad-30}" x2="${W-pad+30}" y1="${AY}" y2="${AY}"/>`;
  for(let y=1980;y<=2020;y+=10) s+=`<line class="bl-tick" x1="${f1(X(y))}" x2="${f1(X(y))}" y1="${AY-6}" y2="${AY+6}"/><text class="bl-dec" x="${f1(X(y))}" y="${AY+236-AY}">${y}</text>`;
  s+=`<text class="bl-dec" x="${pad-30}" y="236" text-anchor="start">1976</text><text class="bl-dec" x="${W-pad+30}" y="236" text-anchor="end">2026</text>`;
  Q.forEach((q,i)=>{const x=BX[i], r=7+(q.mag-5.5)*6.5, up=i%2===0, ly=up?AY-r-44:AY+r+30;
    s+=`<g class="bl-node ${i===cur?"cur":seen.has(i)?"seen":""}" data-i="${i}" tabindex="0" role="button" aria-label="${q.anio}, ${esc(q.lugar)}, magnitud ${q.magTxt}">
      <line class="stem" x1="${f1(x)}" x2="${f1(x)}" y1="${up?ly+6:AY+r}" y2="${up?AY-r:ly-20}"/>
      <circle cx="${f1(x)}" cy="${AY}" r="${f1(r+10)}" fill="transparent"/><circle class="c" cx="${f1(x)}" cy="${AY}" r="${f1(r)}"/>
      ${i===cur?`<circle class="ring" cx="${f1(x)}" cy="${AY}" r="${f1(r)}"/><circle class="ring r2" cx="${f1(x)}" cy="${AY}" r="${f1(r)}"/>`:""}
      <text class="ty" x="${f1(x)}" y="${f1(up?ly-8:ly)}">${q.anio}</text><text class="tl" x="${f1(x)}" y="${f1(up?ly+6:ly+15)}">${esc(q.lugar)}</text></g>`;});
  const mx = markX===null ? pad-30 : markX;
  s+=`<g id="bl-mark" transform="translate(${f1(mx)} ${AY})"><path d="M0 -14 C-9 -14 -12 -6 -9 -1 L0 12 L9 -1 C12 -6 9 -14 0 -14Z" fill="var(--pin)" stroke="var(--bg)" stroke-width="1.5" transform="translate(0 -26)"/><circle cy="-34" r="3.2" fill="var(--bg)"/></g>`;
  $("#bl-svg").innerHTML=s;
  $("#bl-svg").querySelectorAll(".bl-node").forEach(g=>{g.addEventListener("click",()=>{stopPlay(); const i=+g.dataset.i; if(i===cur&&!busy) descend(); else go(i);}); g.addEventListener("keydown",e=>{if(e.key==="Enter"||e.key===" "){e.preventDefault();g.dispatchEvent(new Event("click"));}});});
}
function headIntro(){
  $("#bl-head").className="bl-head";
  $("#bl-head").innerHTML=`<p class="bl-k">1976 – 2026</p><div class="bl-year intro">Medio siglo, diez sismos</div><p class="bl-k" style="font-weight:400;max-width:46ch">Recorre la línea de tiempo: en cada sismo verás dónde ocurrió y qué dejó.</p>`;
  $("#bl-hint").innerHTML=`Presiona <kbd>→</kbd> o toca el primer sismo para empezar`;
}
function headAt(i){
  const q=Q[i], h=$("#bl-head"), m=q.sinMuertos?"0":(q.muertosAprox?"≈":"")+fmt(q.muertos);
  h.className="bl-head"; void h.offsetWidth; h.className="bl-head pop";
  h.innerHTML=`<p class="bl-k num">Sismo ${i+1} de 10 · ${esc(q.fecha)}</p><div class="bl-year num">${q.anio}</div><div class="bl-place">${esc(q.lugar)}</div>
    <div class="bl-chips"><span><b class="num">${esc(q.magTxt.replace(" Mw",""))}</b>magnitud</span><span><b class="num">${esc(q.profTxt.replace("Unos ","≈"))}</b>de profundidad</span><span><b class="num">${m}</b>muertos</span></div>`;
  $("#bl-hint").innerHTML = mode==="line"&&!busy ? `<kbd>Enter</kbd> para ver el mapa · <kbd>→</kbd> siguiente sismo` : `<span class="bl-prog" aria-hidden="true"><span></span></span>Bajando al mapa…`;
}
function moveMarker(i,done){
  const to=BX[i], from=markX===null?BX[0]-90:markX, el=()=>$("#bl-mark");
  const tr=$("#bl-track"); if(tr.scrollWidth>tr.clientWidth) tr.scrollTo({left:to-tr.clientWidth/2,behavior:reduced?"auto":"smooth"});
  if(reduced){markX=to; el().setAttribute("transform",`translate(${f1(to)} ${AY})`); done(); return;}
  const t0=performance.now(), D=Math.min(1100,350+Math.abs(to-from)*1.2); cancelAnimationFrame(mAnim);
  const st=now=>{const k=Math.min(1,(now-t0)/D), e=k<.5?2*k*k:1-Math.pow(-2*k+2,2)/2; markX=from+(to-from)*e; const m=el(); if(m) m.setAttribute("transform",`translate(${f1(markX)} ${AY-Math.sin(k*Math.PI)*10})`); if(k<1) mAnim=requestAnimationFrame(st); else done();};
  mAnim=requestAnimationFrame(st);
}
function setMode(m){ mode=m; const a=$("#app"); a.classList.toggle("line",m==="line"); a.classList.toggle("detail",m==="detail"); $("#b-line").hidden=m==="line"; if(m==="line"){renderBig(); sizeBig();} }
function go(i){
  if(i<0||i>9) return;
  if(busy){ if(phase==="dwell"&&i===cur+0) return; if(phase!=="dwell") return; clearTimeout(dwellT); }
  busy=true; phase="rise";
  const travel=()=>{ phase="move"; if(i!==cur){cmpWith=null;} cur=i; seen.add(i); renderBig(); renderStrip(); headAt(i); const tInfo=performance.now();
    moveMarker(i,()=>{ phase="dwell"; bigKick(Q[i].mag); renderBig(); dwellT=setTimeout(descend, Math.max(0,3000-(performance.now()-tInfo))); }); };
  if(mode==="detail"){ setMode("line"); setTimeout(travel, reduced?0:520); } else travel();
}
function descend(){
  if(cur<0) return; clearTimeout(dwellT); busy=false; phase="";
  setMode("detail"); renderMap(); renderNote(); renderStrip(); kick(Q[cur].mag);
}
function showLine(){ stopPlay(); setMode("line"); if(cur>=0){ headAt(cur);} else headIntro(); }
$("#b-line").addEventListener("click",showLine);
$("#prev").addEventListener("click",()=>{stopPlay();go(cur-1);});
$("#next").addEventListener("click",()=>{stopPlay();go(cur+1);});
let dragMoved=false;
$("#map").addEventListener("click",()=>{ if(dragMoved){dragMoved=false;return;} stopPlay(); if(cur<9) go(cur+1);});
/* ---------- Zoom y arrastre del mapa ---------- */
function setVB(v){ const w=Math.max(40,Math.min(340,v[2])), h=w*360/300; const cx=v[0]+v[2]/2, cy=v[1]+v[3]/2;
  let x=cx-w/2, y=cy-h/2; x=Math.max(-60,Math.min(360-w,x)); y=Math.max(-40,Math.min(400-h,y)); vb=[x,y,w,h]; cancelAnimationFrame(anim); $("#map").setAttribute("viewBox",vb.map(f1).join(" ")); $("#map").style.setProperty("--zs",Math.min(1.6,Math.max(.35,vb[2]/193.5)).toFixed(3)); }
function svgPt(cx,cy){ const r=$("#map").getBoundingClientRect(), s=Math.max(vb[2]/r.width,vb[3]/r.height), ox=(r.width-vb[2]/s)/2, oy=(r.height-vb[3]/s)/2; return [vb[0]+(cx-r.left-ox)*s, vb[1]+(cy-r.top-oy)*s, s]; }
function zoomAt(f,px,py){ const [sx,sy]=svgPt(px,py); const w=vb[2]/f; const nw=Math.max(40,Math.min(340,w)), k=nw/vb[2]; setVB([sx-(sx-vb[0])*k, sy-(sy-vb[1])*k, nw, nw*360/300]); }
function zoomCenter(f){ const r=$("#map").getBoundingClientRect(); zoomAt(f,r.left+r.width/2,r.top+r.height/2); }
$("#z-in").addEventListener("click",e=>{e.stopPropagation();zoomCenter(1.4);});
$("#z-out").addEventListener("click",e=>{e.stopPropagation();zoomCenter(1/1.4);});
$("#z-reset").addEventListener("click",e=>{e.stopPropagation(); if(cur>=0) zoomTo(Q[cur]);});
$("#map").addEventListener("wheel",e=>{e.preventDefault(); zoomAt(e.deltaY<0?1.15:1/1.15,e.clientX,e.clientY);},{passive:false});
const ptrs=new Map(); let pinch0=null, drag0=null;
$("#map").addEventListener("pointerdown",e=>{ ptrs.set(e.pointerId,[e.clientX,e.clientY]); $("#map").setPointerCapture(e.pointerId); dragMoved=false;
  if(ptrs.size===1) drag0={x:e.clientX,y:e.clientY,vb:vb.slice()}; else if(ptrs.size===2){const [a,b]=[...ptrs.values()]; pinch0={d:Math.hypot(a[0]-b[0],a[1]-b[1]),w:vb[2]}; drag0=null;} });
$("#map").addEventListener("pointermove",e=>{ if(!ptrs.has(e.pointerId)) return; ptrs.set(e.pointerId,[e.clientX,e.clientY]);
  if(ptrs.size===2&&pinch0){const [a,b]=[...ptrs.values()], d=Math.hypot(a[0]-b[0],a[1]-b[1]); const f=d/pinch0.d; const mx=(a[0]+b[0])/2,my=(a[1]+b[1])/2; const target=pinch0.w/f; zoomAt(vb[2]/target,mx,my); dragMoved=true; return;}
  if(drag0){const dx=e.clientX-drag0.x, dy=e.clientY-drag0.y; if(Math.hypot(dx,dy)>5){dragMoved=true; $("#map").classList.add("grab");}
    if(dragMoved){const r=$("#map").getBoundingClientRect(), s=Math.max(drag0.vb[2]/r.width,drag0.vb[3]/r.height); setVB([drag0.vb[0]-dx*s,drag0.vb[1]-dy*s,drag0.vb[2],drag0.vb[3]]);}} });
function endPtr(e){ ptrs.delete(e.pointerId); if(ptrs.size<2) pinch0=null; if(ptrs.size===0){drag0=null; $("#map").classList.remove("grab");} }
$("#map").addEventListener("pointerup",endPtr); $("#map").addEventListener("pointercancel",endPtr);

/* ---------- Comparar ---------- */
function openCmp(){
  const A=Q[cur], B=Q[cmpWith];
  const M=[{k:"mag",t:"Magnitud",max:9,sc:"Escala de 0 a 9",v:q=>q.magTxt.replace(" Mw","")},{k:"prof",t:"Profundidad",max:180,sc:"Escala de 0 a 180 km",v:q=>q.profTxt.replace("Unos ","≈ ")},{k:"muertos",t:"Muertos",max:1200,sc:"Escala de 0 a 1.200",v:q=>q.sinMuertos?"0 reportados":(q.muertosAprox?"≈ ":"")+fmt(q.muertos)}];
  const row=(q,col)=>m=>{const w=Math.max(q[m.k]>0?1.5:0,q[m.k]/m.max*100);return `<div class="br"><div class="lab"><span><i class="sw" style="background:var(${col})"></i>${q.anio} ${esc(q.lugar)}</span><b class="num">${esc(m.v(q))}</b></div><div class="bt"><div class="bf" style="width:${f1(w)}%;background:var(${col})"></div></div></div>`;};
  const dm=A.mag-B.mag; let e;
  if(Math.abs(dm)<.05) e="Tienen la misma magnitud, así que liberaron una energía parecida. Sus daños dependen de la profundidad, la distancia a las ciudades y cómo se construyó.";
  else{const big=dm>0?A:B, sm=dm>0?B:A, f=Math.pow(10,1.5*Math.abs(dm)); e=`El de ${big.lugar} (${big.anio}) liberó unas <b>${f>=10?fmt(Math.round(f)):f.toFixed(1).replace(".",",")} veces</b> la energía del de ${sm.lugar} (${sm.anio}), según la relación del USGS: cada punto de magnitud equivale a unas 32 veces más energía.${(A.magPC||B.magPC)?" La magnitud del Viejo Caldas está en disputa entre fuentes.":""}`;}
  $("#cmp").innerHTML=`${PIN}<button class="btn close" type="button" id="cmp-close">Cerrar</button>
    <h3 id="cmp-t">${A.anio} ${esc(A.lugar)} frente a ${B.anio} ${esc(B.lugar)}</h3>
    <p class="sub">Cada dato tiene su propia escala. En el mapa, el segundo sismo aparece con ondas azules.</p>
    <div class="mt">${M.map(m=>`<div><h4>${m.t}</h4><p class="sc">${m.sc}</p>${row(A,"--serie-a")(m)}${row(B,"--serie-b")(m)}</div>`).join("")}</div>
    <p class="energy">${e}</p>`;
  $("#modal").hidden=false; $("#cmp-close").focus();
  $("#cmp-close").addEventListener("click",closeCmp);
}
function closeCmp(){ $("#modal").hidden=true; const s=$("#cmp-sel"); if(s) s.focus(); }
$("#modal").addEventListener("click",e=>{if(e.target.id==="modal") closeCmp();});

/* ---------- Reproducción, fuentes, pantalla completa ---------- */
function play(){ if(playing) return stopPlay(); go(cur>=9?0:cur+1); playing=setInterval(()=>{ if(busy) return; if(cur>=9) stopPlay(); else go(cur+1); },5200);
  $("#play").setAttribute("aria-pressed","true"); $("#play-t").textContent="Pausa"; $("#play-ico").innerHTML='<path d="M4 3h3v10H4zM9 3h3v10H9z" fill="currentColor"/>'; }
function stopPlay(){ if(!playing) return; clearInterval(playing); playing=null;
  $("#play").setAttribute("aria-pressed","false"); $("#play-t").textContent="Automático"; $("#play-ico").innerHTML='<path d="M5 3v10l8-5z" fill="currentColor"/>'; }
$("#play").addEventListener("click",play);
$("#src-list").innerHTML=Object.values(S).map(s=>`<li><a href="${s.u}" target="_blank" rel="noopener">${esc(s.t)}</a></li>`).join("");
$("#b-src").addEventListener("click",()=>{stopPlay();$("#panel").hidden=false;$("#src-close").focus();});
$("#src-close").addEventListener("click",()=>{$("#panel").hidden=true;$("#b-src").focus();});
$("#b-full").addEventListener("click",async()=>{try{document.fullscreenElement?await document.exitFullscreen():await document.documentElement.requestFullscreen();}catch(e){}});

document.addEventListener("keydown",e=>{
  if(e.key==="Escape"){ if(!$("#modal").hidden) closeCmp(); else if(!$("#panel").hidden){$("#panel").hidden=true;} return; }
  if(!$("#modal").hidden||!$("#panel").hidden) return;
  if(!$("#cover").hidden){ if(e.key==="Enter"||e.key==="ArrowRight"||e.key===" "){e.preventDefault();start();} return; }
  const t=e.target.tagName; if(t==="SELECT") return;
  if(e.key==="ArrowRight"){e.preventDefault();stopPlay(); if(busy&&phase==="dwell") descend(); else go(cur+1);}
  if(e.key==="ArrowLeft"){e.preventDefault();stopPlay(); if(cur>0) go(cur-1);}
  if(e.key==="Enter"&&mode==="line"&&cur>=0&&(t!=="BUTTON")&&!(e.target.classList&&e.target.classList.contains("bl-node"))){e.preventDefault(); if(!busy||phase==="dwell") descend();}
});
let tx=null;
$(".stage").addEventListener("touchstart",e=>{tx=e.target.closest&&e.target.closest("#map")?null:[e.touches[0].clientX,e.touches[0].clientY];},{passive:true});
$(".stage").addEventListener("touchend",e=>{if(!tx)return;const dx=e.changedTouches[0].clientX-tx[0],dy=e.changedTouches[0].clientY-tx[1];tx=null;if(Math.abs(dx)>60&&Math.abs(dx)>Math.abs(dy)*1.5){stopPlay();go(cur+(dx<0?1:-1));}},{passive:true});

function start(){ $("#cover").hidden=true; $("#app").hidden=false; setMode("line"); headIntro(); sizeSeis(); const n=$("#bl-svg .bl-node"); if(n) n.focus({preventScroll:true}); }
$("#go").addEventListener("click",start);

/* ---------- Fondo: curvas de nivel + sismógrafo de la franja ---------- */
const topo=$("#topo"), tg=topo.getContext("2d");
function drawTopo(){const d=Math.min(2,devicePixelRatio||1),W=innerWidth,H=innerHeight;topo.width=W*d;topo.height=H*d;tg.setTransform(d,0,0,d,0,0);
  tg.fillStyle=css("--bg");tg.fillRect(0,0,W,H);tg.strokeStyle=css("--line");tg.lineWidth=1;
  [[W*.08,H*.2],[W*.95,H*.85]].forEach(([cx,cy],c)=>{for(let r=0;r<14;r++){tg.beginPath();for(let a=0;a<=64;a++){const th=a/64*Math.PI*2,rr=40+r*38+Math.sin(th*3+r+c)*12+Math.cos(th*5-r)*8;const x=cx+Math.cos(th)*rr*1.3,y=cy+Math.sin(th)*rr;a?tg.lineTo(x,y):tg.moveTo(x,y);}tg.globalAlpha=.55;tg.stroke();}});tg.globalAlpha=1;}
const sc=$("#seis"), sg=sc.getContext("2d"); let tr=[], burst=0, bmag=0, tk=0;
function sizeSeis(){if(!sc.clientWidth)return;const d=Math.min(2,devicePixelRatio||1);sc.width=sc.clientWidth*d;sc.height=sc.clientHeight*d;sg.setTransform(d,0,0,d,0,0);tr=new Array(Math.ceil(sc.clientWidth/2)).fill(0);}
function kick(m){burst=1;bmag=Math.max(.2,(m-5)/3);}
function seisFrame(){
  tk++; const W=sc.clientWidth,H=sc.clientHeight; if(!W){requestAnimationFrame(seisFrame);return;} sg.clearRect(0,0,W,H);
  const a=1.5+burst*bmag*H*.32; tr.shift(); tr.push((Math.random()-.5)*2*a); if(burst>0) burst=Math.max(0,burst-.008);
  sg.strokeStyle=css("--ink-3"); sg.globalAlpha=.2; for(let x=0;x<W;x+=50){sg.beginPath();sg.moveTo(x+.5,0);sg.lineTo(x+.5,H);sg.stroke();}
  sg.globalAlpha=.55; sg.strokeStyle=burst>.05?css("--rojo"):css("--accent"); sg.lineWidth=1.2; sg.beginPath();
  tr.forEach((v,i)=>i?sg.lineTo(i*2,H*.5+v):sg.moveTo(0,H*.5+v)); sg.stroke(); sg.globalAlpha=1;
  if(!reduced) requestAnimationFrame(seisFrame);
}
const bc=$("#bl-seis"), bg2=bc.getContext("2d"); let bb=0,bm=0,bt=0;
function sizeBig(){const w=bc.clientWidth,h=bc.clientHeight; if(!w) return; const d=Math.min(2,devicePixelRatio||1); bc.width=w*d; bc.height=h*d; bg2.setTransform(d,0,0,d,0,0);}
function bigKick(m){bb=1;bm=Math.max(.25,(m-5)/3);}
function bigFrame(){
  const W=bc.clientWidth,H=bc.clientHeight;
  if(W && mode==="line"){ bt++; bg2.clearRect(0,0,W,H); const mx=markX===null?-999:markX;
    bg2.strokeStyle=bb>.05?css("--rojo"):css("--accent"); bg2.globalAlpha=.55; bg2.lineWidth=1.3; bg2.beginPath();
    for(let x=0;x<=W;x+=2){ const g=Math.exp(-Math.pow((x-mx)/(70+bm*60),2)); const a=1.2+bb*bm*70*g+ (mode==="line"?.6:0); const y=AY+(Math.sin(x*.9+bt*.6)*.5+ (Math.random()-.5))*a; x?bg2.lineTo(x,y):bg2.moveTo(x,y);} bg2.stroke(); bg2.globalAlpha=1;
    if(bb>0) bb=Math.max(0,bb-.007); }
  if(!reduced) requestAnimationFrame(bigFrame);
}
function resizeAll(){drawTopo();sizeSeis(); if(mode==="line"){renderBig();sizeBig();} if(!$("#cover").hidden||cur<0) return; zoomTo(Q[cur]);}
addEventListener("resize",()=>{clearTimeout(window._r);window._r=setTimeout(resizeAll,120);});
matchMedia("(prefers-color-scheme: dark)").addEventListener("change",drawTopo);
new MutationObserver(drawTopo).observe(document.documentElement,{attributes:true,attributeFilter:["data-theme"]});
drawTopo(); sizeSeis(); seisFrame(); bigFrame();
renderStrip();
